// Render product card
function renderProductCard(product) {
    return `
        <div class="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-xl transition flex flex-col h-full group cursor-pointer" onclick="navigateToProduct(${product.id})">
            <img src="${product.image_url || 'https://via.placeholder.com/300'}" 
                alt="${product.name}" 
                class="w-full h-48 object-contain">

            <div class="p-4 flex flex-col flex-grow">
                <p class="text-gray-600 text-sm mb-4 line-clamp-2">
                    ${product.description || 'Sin descripción'}
                </p>

                <div class="mt-auto">
                    <div class="flex items-center justify-between">
                        <div class="flex flex-col">
                            <h3 class="text-sm font-bold text-gray-900 line-clamp-2">
                                ${product.name}
                            </h3>
                            <span class="text-lg font-bold text-red-600">
                                $${parseFloat(product.price).toFixed(2)}
                            </span>
                        </div>

                        <button 
                            onclick="addToCart(${JSON.stringify(product).replace(/"/g, '&quot;')}, 1); event.stopPropagation();" 
                            class="opacity-0 group-hover:opacity-100 transition duration-200 bg-red-600 text-white p-2 rounded-full hover:bg-red-700">
                            
                            <svg xmlns="http://www.w3.org/2000/svg" 
                                fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" 
                                class="w-5 h-5">
                                <path stroke-linecap="round" stroke-linejoin="round" 
                                    d="M2.25 3h1.386c.51 0 .955.343 1.087.835L5.76 8.25m0 0h12.49c.718 0 1.262.674 1.108 1.375l-1.5 6A1.125 1.125 0 0116.77 16.5H8.23a1.125 1.125 0 01-1.088-.875L5.76 8.25zm0 0L4.5 4.5m4.5 12a.75.75 0 100 1.5.75.75 0 000-1.5zm7.5 0a.75.75 0 100 1.5.75.75 0 000-1.5z" />
                            </svg>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    `;
}

// Navigate to product detail page
function navigateToProduct(productId) {
    window.location.href = `product.html?id=${productId}`;
}

// Render breadcrumb
function renderBreadcrumb(items) {
    return `
        <div class="bg-gray-50 border-b border-gray-200">
            <div class="max-w-7xl mx-auto px-4 py-3 text-sm">
                ${items.map((item, idx) => `
                    ${idx > 0 ? '<span class="text-gray-400 mx-2">/</span>' : ''}
                    ${item.href
            ? `<a href="${item.href}" class="text-red-600 hover:text-red-700">${item.label}</a>`
            : `<span class="text-gray-600">${item.label}</span>`
        }
                `).join('')}
            </div>
        </div>
    `;
}

// Render input field
function renderInput(id, label, type = 'text', required = false) {
    return `
        <div>
            <label class="block text-gray-700 uppercase text-xs tracking-wider font-bold mb-2">
                ${label}${required ? ' *' : ''}
            </label>
            <input 
                type="${type}" 
                id="${id}" 
                ${required ? 'required' : ''}
                class="w-full bg-white border border-gray-300 px-4 py-2 text-gray-900 focus:border-red-600 focus:outline-none"
            >
        </div>
    `;
}

// Show notification
function showNotification(message, type = 'success', duration = 3000) {
    const notification = document.createElement('div');
    const bgColor = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

    notification.innerHTML = `
        <div class="${bgColor} text-white px-6 py-3 rounded shadow-lg fixed top-4 right-4 z-[9999]">
            ${message}
        </div>
    `;

    document.body.appendChild(notification);

    setTimeout(() => notification.remove(), duration);
}

// Show confirm modal
function showConfirmModal(title, message, onConfirm, onCancel) {
    const modal = document.createElement('div');
    modal.innerHTML = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[9998]">
            <div class="bg-white p-8 max-w-md">
                <h2 class="text-2xl font-bold text-gray-900 uppercase mb-4">${title}</h2>
                <p class="text-gray-600 mb-8">${message}</p>
                <div class="flex gap-4">
                    <button id="confirm-btn" class="flex-1 px-6 py-2 bg-red-600 text-white font-bold uppercase hover:bg-red-700 transition">
                        Confirmar
                    </button>
                    <button id="cancel-btn" class="flex-1 px-6 py-2 bg-gray-300 text-gray-900 font-bold uppercase hover:bg-gray-400 transition">
                        Cancelar
                    </button>
                </div>
            </div>
        </div>
    `;

    document.body.appendChild(modal);

    document.getElementById('confirm-btn').addEventListener('click', () => {
        onConfirm();
        modal.remove();
    });

    document.getElementById('cancel-btn').addEventListener('click', () => {
        if (onCancel) onCancel();
        modal.remove();
    });
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    renderNavbar();
    renderFooter();
});